def chk(t, p, v):
    if t=='R': return v.strip().lower().startswith(p.strip().lower())
    if t=='K': return all(re.search(re.escape(k), v, re.I) for k in p)
    if t=='F': return len(re.findall(re.escape(p[0]), v, re.I)) >= p[1]
    if t=='E': return v.strip().strip('"').lower().endswith(p.strip().lower())
    if t=='S':
        vl=v.lower()
        pat = r"\s*p\.\s?p\.\s?s.*$" if p=='P.P.S' else (r"\s*p\.\s?s\..*$" if p=='P.S.' else r"\s*"+re.escape(p.lower())+r".*$")
        return bool(re.findall(pat, vl, flags=re.MULTILINE))
    if t=='Q': s=v.strip(); return len(s)>1 and s[0]=='"' and s[-1]=='"'
    if t=='C': return any(o in v for o in p)
    if t=='M': return len(re.split(r"\s?SECTION\s?\d+\s?", v))-1 >= p
    if t=='T':
        rs=v.split('******'); val=[]
        for i,r_ in enumerate(rs):
            if not r_.strip():
                if i!=0 and i!=len(rs)-1: return False
            else: val.append(r_)
        return len(val)==2 and val[0].strip()!=val[1].strip()
    if t=='N': return ',' not in v
    if t=='L': return v==v.lower()
    if t=='U': return v==v.upper()
    if t=='W': return len(re.findall(r"\w+", v))>=p
    if t=='w': return len(re.findall(r"\w+", v))<p
    if t=='P':
        ps=re.split(r"\s?\*\*\*\s?", v); num=len(ps)
        for i,pp in enumerate(ps):
            if not pp.strip():
                if i==0 or i==len(ps)-1: num-=1
                else: return False
        return num==p
    if t=='Ti': return any(x.lstrip('<').rstrip('>').strip() for x in re.findall(r"<<[^\n]+>>", v))
    if t=='B': return len(re.findall(r"^\s*\*[^\*].*$", v, flags=re.M))+len(re.findall(r"^\s*-.*$", v, flags=re.M))==p
    if t=='H':
