    W=load(P+f'{L}.self_attn.q_proj.weight').numpy(); B=base_q(L); dd=np.abs(W-B).sum(1)
    print(L, 'changed rows', int((dd>0).sum()), 'heads', sorted(set(int(i)//512 for i in np.where(dd>0)[0])))
```

